-- Chapter 22 fingerprint: the exact query used for ch22-baseline.json (2026-11-06, before any write).
with t as (select id, a_level_topic_code code from topics where a_level_topic_code like '22.%'), p as (select p.* from problems p join t on t.id=p.topic_id) select t.code, p.curriculum_id, count(*) n, md5(string_agg(p.id::text||coalesce(p.question_text,'')||coalesce(p.answer_correct,'')||coalesce(p.explanation,'')||coalesce(p.difficulty_level::text,'')||coalesce(p.points::text,'')||coalesce(p.updated_at::text,''), '|' order by p.id)) h, (select md5(string_agg(o.id::text||o.option_text||coalesce(o.is_correct::text,''), '|' order by o.id)) from problem_options o where o.problem_id in (select id from problems p2 where p2.topic_id=t.id and p2.curriculum_id=p.curriculum_id)) oh from p join t on t.id=p.topic_id group by t.id, t.code, p.curriculum_id order by 1,2
